"use strict";(self.webpackChunksnek_taiwan=self.webpackChunksnek_taiwan||[]).push([["9351"],{930(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"snek-genesis-pass-nft","metadata":{"permalink":"/en/blog/snek-genesis-pass-nft","source":"@site/i18n/en/docusaurus-plugin-content-blog/2026-10-16-snek-genesis-pass-nft.md","title":"SNEK Genesis VIP Pass NFT Officially Launched! Interactive 3D Digital Wallet Pass Now Live","description":"The SNEK Taiwan community is proud to officially unveil the exclusive \\"SNEK Genesis VIP Pass\\" NFT collection! Limited to just 100 unique cards, this genesis collection represents permanent honorary recognition for early core supporters and community builders.","date":"2026-10-16T00:00:00.000Z","tags":[{"inline":false,"label":"SNEK","permalink":"/en/blog/tags/snek","description":"SNEK token announcements and updates"},{"inline":false,"label":"Cardano","permalink":"/en/blog/tags/cardano","description":"Cardano blockchain ecosystem news"},{"inline":false,"label":"Taiwan Community","permalink":"/en/blog/tags/taiwan","description":"Taiwan local community updates and events"},{"inline":false,"label":"Announcements","permalink":"/en/blog/tags/announcement","description":"Official announcements and key milestones"}],"readingTime":1.51,"hasTruncateMarker":true,"authors":[{"name":"SNEK Taiwan Community","title":"Taiwan Community Contributors","url":"https://www.snek.com.tw","key":"snek_team","page":null}],"frontMatter":{"slug":"snek-genesis-pass-nft","title":"SNEK Genesis VIP Pass NFT Officially Launched! Interactive 3D Digital Wallet Pass Now Live","authors":["snek_team"],"tags":["snek","cardano","taiwan","announcement"]},"unlisted":false,"nextItem":{"title":"SNEK Taiwan Website Featured on SNEK Timeline!","permalink":"/en/blog/snek-timeline-featured"}},"content":"The SNEK Taiwan community is proud to officially unveil the exclusive \\"**SNEK Genesis VIP Pass**\\" NFT collection! Limited to just 100 unique cards, this genesis collection represents permanent honorary recognition for early core supporters and community builders.\\n\\nSimultaneously, the official dedicated digital wallet pass carrier ([snek.com.tw/pass](/pass)) is now live, empowering cardholders to interact with their NFTs directly in stunning 3D on the web!\\n\\n{/* truncate */}\\n\\n![SNEK Genesis Pass #002](/img/pass/cards/SnekPass002.webp)\\n\\n---\\n\\n## On-Chain Minting & Verification Details\\n\\nTo ensure absolute transparency and verifiable authenticity across the global Cardano ecosystem, every pass is minted on Cardano Mainnet:\\n\\n- **Blockchain**: Cardano Mainnet\\n- **Total Supply**: Limited to 100 Passes (First batch minted for 19 genesis holders)\\n- **Official Policy ID**:\\n  ```text\\n  9ae0010772d9bd27533656be72b65a1c72410287f93551b58faa5702\\n  ```\\n- **Asset Name Format**: `SnekPass001` ~ `SnekPass100`\\n\\n> \u26A0\uFE0F **Security Notice**: Always verify the official Policy ID above before trading or interacting with assets. Beware of unauthorized copies or counterfeit tokens.\\n\\n---\\n\\n## What Can You Do on the Website?\\n\\nThe website has debuted a dedicated [**3D Digital Wallet Pass Carrier**](/pass), providing holders with an immersive, interactive Web3 experience:\\n\\n![3D Digital Wallet Pass Features Preview](/img/pass/pass_schematic_preview.webp)\\n\\n- **Zero-Signature Safe Loading**: Enter any public Cardano wallet address or ADA Handle to automatically discover your passes. No wallet connection or transaction signing required\u2014zero risk of private key leakage.\\n- **Realistic 3D Tilt & Holographic Lighting**: Experience interactive 3D physics with cursor parallax and mobile gyroscope support. Click or tap to flip the card and reveal dynamic security phrases on the back.\\n- **Multi-Pass Wallet Aggregation**: If a single wallet holds multiple passes, the carrier automatically groups them with an intuitive pass switcher.\\n- **Dedicated Payment QR & PWA Install**: The reverse side features a personalized ADA receive QR code, with full Progressive Web App (PWA) support to save the pass directly to your mobile home screen for instant access."},{"id":"snek-timeline-featured","metadata":{"permalink":"/en/blog/snek-timeline-featured","source":"@site/i18n/en/docusaurus-plugin-content-blog/2026-10-10-snek-timeline-featured.md","title":"SNEK Taiwan Website Featured on SNEK Timeline!","description":"A momentous milestone for the SNEK Taiwan community! We are thrilled to share that the official SNEK Taiwan website (snek.com.tw) was officially recognized and immortalized as a global Community Milestone on SNEK Timeline on October 9, 2026!","date":"2026-10-10T00:00:00.000Z","tags":[{"inline":false,"label":"SNEK","permalink":"/en/blog/tags/snek","description":"SNEK token announcements and updates"},{"inline":false,"label":"Cardano","permalink":"/en/blog/tags/cardano","description":"Cardano blockchain ecosystem news"},{"inline":false,"label":"Taiwan Community","permalink":"/en/blog/tags/taiwan","description":"Taiwan local community updates and events"},{"inline":false,"label":"Announcements","permalink":"/en/blog/tags/announcement","description":"Official announcements and key milestones"}],"readingTime":1.78,"hasTruncateMarker":true,"authors":[{"name":"SNEK Taiwan Community","title":"Taiwan Community Contributors","url":"https://www.snek.com.tw","key":"snek_team","page":null}],"frontMatter":{"slug":"snek-timeline-featured","title":"SNEK Taiwan Website Featured on SNEK Timeline!","authors":["snek_team"],"tags":["snek","cardano","taiwan","announcement"]},"unlisted":false,"prevItem":{"title":"SNEK Genesis VIP Pass NFT Officially Launched! Interactive 3D Digital Wallet Pass Now Live","permalink":"/en/blog/snek-genesis-pass-nft"},"nextItem":{"title":"SNEK Taiwan Community Official Website Officially Launched","permalink":"/en/blog/welcome-snek-taiwan"}},"content":"A momentous milestone for the SNEK Taiwan community! We are thrilled to share that the official SNEK Taiwan website (snek.com.tw) was officially recognized and immortalized as a global Community Milestone on [SNEK Timeline](https://snektimeline.com/) on October 9, 2026!\\n\\n{/* truncate */}\\n\\n![SNEK Timeline Milestone](/img/timeline/2026-10-09_SNEK_TAIWAN_WEBSITE_LIVE.webp)\\n\\n---\\n\\n## About SNEK Timeline\\n\\n[SNEK Timeline](https://snektimeline.com/) is the authoritative historical chronicle maintained by The Snekverse (@snekcoinprice) and dedicated contributors. It chronicles every significant event in SNEK history since its fair launch in 2023 \u2014 including major ecosystem launches, Tier-1 exchange listings, global merchandise partnerships, and regional community milestones.\\n\\nBeing featured in this official chronicle signifies that our local Taiwan grassroots movement is fully acknowledged and celebrated across the international Cardano and SNEK ecosystems.\\n\\n---\\n\\n## Feature Summary on SNEK Timeline\\n\\nUnder the October 9, 2026 timeline entry, the milestone is documented as \\"**SNEK Taiwan Website Officially Live!**\\":\\n\\n> \\"Snek 1u announced the official launch of the SNEK Taiwan community website at snek.com.tw. The Traditional Chinese hub targets local Web3 enthusiasts with token resources, ecosystem updates, and community guidelines focused on positive discussion. It also directs users to a LINE group to grow the regional Snek presence on Cardano.\\"\\n> \\n> \u2014\u2014 Excerpt from [SNEK Timeline](https://snektimeline.com/)\\n\\nThe chronicle highlights the initiative led by community admin SNEK 1u, acknowledging our mission to provide accurate education, lower Web3 barriers, and unite local holders through our thriving LINE hub.\\n\\n---\\n\\n## Gratitude to the Entire Taiwan Snek Army\\n\\nThis achievement belongs to every supporter and community builder:\\n\\n- Sincere gratitude to admin **SNEK 1u** (Threads: [@snek_1u](https://www.threads.com/@snek_1u)) for leadership and coordination.\\n- Thank you to all volunteers contributing to translations, copywriting, web design, and meme creations.\\n- A huge shout-out to all community members keeping discussions friendly, rational, and full of positive vibes!\\n\\n---\\n\\n## Looking Forward\\n\\nBeing included on SNEK Timeline is a huge honor, but our journey is just getting started! We will continue refining educational guides, tracking Cardano on-chain innovations, and expanding fun community events.\\n\\nStay connected with us:\\n\\n- [View on SNEK Timeline](https://snektimeline.com/)\\n- [Official Announcement by SNEK 1u on X](https://x.com/snek_1u/status/2108439209774313830)\\n- [Join the SNEK Taiwan Community Hub](/#snek-pass)"},{"id":"welcome-snek-taiwan","metadata":{"permalink":"/en/blog/welcome-snek-taiwan","source":"@site/i18n/en/docusaurus-plugin-content-blog/2026-10-08-welcome-snek-taiwan.md","title":"SNEK Taiwan Community Official Website Officially Launched","description":"Welcome to the official website of the SNEK Taiwan Community!","date":"2026-10-08T00:00:00.000Z","tags":[{"inline":false,"label":"SNEK","permalink":"/en/blog/tags/snek","description":"SNEK token announcements and updates"},{"inline":false,"label":"Cardano","permalink":"/en/blog/tags/cardano","description":"Cardano blockchain ecosystem news"},{"inline":false,"label":"Taiwan Community","permalink":"/en/blog/tags/taiwan","description":"Taiwan local community updates and events"},{"inline":false,"label":"Announcements","permalink":"/en/blog/tags/announcement","description":"Official announcements and key milestones"}],"readingTime":0.8,"hasTruncateMarker":true,"authors":[{"name":"SNEK Taiwan Community","title":"Taiwan Community Contributors","url":"https://www.snek.com.tw","key":"snek_team","page":null}],"frontMatter":{"slug":"welcome-snek-taiwan","title":"SNEK Taiwan Community Official Website Officially Launched","authors":["snek_team"],"tags":["snek","cardano","taiwan","announcement"]},"unlisted":false,"prevItem":{"title":"SNEK Taiwan Website Featured on SNEK Timeline!","permalink":"/en/blog/snek-timeline-featured"}},"content":"Welcome to the official website of the SNEK Taiwan Community!\\n\\nThis website is dedicated to providing Traditional Chinese and global crypto enthusiasts with clear, authentic, and comprehensive information about Cardano\'s premier cultural token, $SNEK. We strive to lower entry barriers to Web3, cultivate community consensus, and spread the vibrant, friendly SNEK meme culture.\\n\\n{/* truncate */}\\n\\n## Core Features of the Website\\n\\n- **Snek Army Core Rules**: Embracing our community consensus \u2014 No FUD, SNEK & chill only, and messaging admin SNEK 1u ([@snek_1u on Threads](https://www.threads.com/@snek_1u)) with your holding position before applying.\\n- **Newcomer Toolbox**: Curated one-stop portal for the SNEK.com official site, Taiwan LINE community, Telegram discussion group, and official X (@snek).\\n- **Local Community Hub**: Connecting members via our active LINE and Telegram channels for newcomer support and daily banter.\\n- **Bilingual Experience**: Built with full Traditional Chinese and English support to welcome global SNEK believers.\\n\\nFeel free to explore our website and join our community channels to connect with fellow SNEK holders!"}]}}')}}]);